"def can_partition(nums):
    total_sum = sum(nums)
    # If the total sum is odd, it's impossible to split into two equal integer subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    # Use a set to track all possible subset sums reachable
    dp = {0}

    for num in nums:
        # Create a new set to store sums reachable after including current num
        new_sums = set()
        for s in dp:
            if s + num <= target:
                new_sums.add(s + num)
        dp.update(new_sums)

        # Optimization: return early if the target is already reached
        if target in dp:
            return True

    return target in dp"

